(async()=>{const $=s=>document.querySelector(s),E=OwaysAPI.escape,slug=new URLSearchParams(location.search).get('slug')||'',durationUnits={day:'يوم',week:'أسبوع',month:'شهر',year:'سنة'},stageNames={before_order:'قبل الاشتراك',during_activation:'أثناء التفعيل',after_completion:'بعد اكتمال الخدمة'};const money=p=>p.price===null||p.pricing_mode==='quote'?'يُحدّد بعرض سعر':E(p.price)+' '+E(p.currency);function overview(s){$('#service-overview').innerHTML=`<article class="service-overview"><div><div class="eyebrow">تفاصيل الخدمة</div><h1>${E(s.name)}</h1><p class="service-description">${E(s.description)}</p><ul class="service-features">${(Array.isArray(s.features)?s.features:[]).map(feature=>`<li><span aria-hidden="true">✓</span>${E(feature)}</li>`).join('')}</ul></div>${s.images?.[0]?.src?`<img src="${E(s.images[0].src)}" alt="${E(s.images[0].alt||s.name)}" class="service-main-image">`:'<div class="service-detail-symbol" aria-hidden="true">✦</div>'}</article>`}
try{if(!slug)throw Error('اختر الخدمة من الصفحة الرئيسية.');let catalog,catalogError='';try{catalog=await OwaysAPI.request('/api/catalog')}catch(error){catalog={services:[]};catalogError=error.message}const showcase=[...OWAYS.subscriptions,...OWAYS.web].find(s=>s.id===slug);const service=catalog.services.find(s=>s.slug===slug)||catalog.services.find(s=>showcase&&s.name.trim().toLowerCase()===showcase.name.trim().toLowerCase());if(!service){if(!showcase)throw Error(catalogError||'هذه الخدمة غير متاحة حاليًا.');overview({name:showcase.name,description:showcase.desc,features:showcase.features});$('#service-packages').innerHTML=`<section class="portal-panel"><h2>تفاصيل السعر والتنفيذ</h2><p>هذه خدمة ضمن العرض التعريفي. الباقات والأسعار والمدة ومتطلبات التفعيل لم تُنشر بعد؛ يوضّحها الدعم قبل تأكيد الطلب.</p><a class="button" href="/account?intent=support&reason=${encodeURIComponent('أرغب في معرفة تفاصيل '+showcase.name)}">الاستفسار عن الخدمة ←</a></section>`;$('#service-feedback').textContent=catalogError?'تعذر تحميل الباقات المنشورة؛ تفاصيل العرض أدناه تعريفيّة فقط.':'';return}document.title=service.name+' | أويس تك';overview(service);$('#service-feedback').textContent='';if(!service.packages.length){$('#service-packages').innerHTML='<p class="portal-note">لا توجد باقات متاحة لهذه الخدمة حاليًا.</p>';return}$('#service-packages').innerHTML='<div class="section-head service-packages-heading"><div><div class="eyebrow">اختر ما يناسبك</div><h2>الباقات وطريقة التفعيل</h2><p>راجع التفاصيل والمتطلبات، ثم تابع لتعبئة بيانات طلبك.</p></div></div><div class="service-package-grid">'+service.packages.map(p=>`<article class="service-package-card"><h3>${E(p.name)}</h3><div class="service-package-price"><bdi dir="ltr">${money(p)}</bdi></div><dl class="service-package-facts"><div><dt>نوع الخدمة</dt><dd>${service.kind==='subscription'?'اشتراك':'خدمة لمرة واحدة'}</dd></div><div><dt>المدة</dt><dd>${p.duration_value?E(p.duration_value)+' '+E(durationUnits[p.duration_unit]||p.duration_unit):'تُوضّح حسب نطاق الخدمة'}</dd></div><div><dt>طريقة التفعيل</dt><dd>${E(p.activation_method||'بمساعدة الدعم')}</dd></div></dl><section class="service-requirements"><h4>ما تحتاجه لإتمام الطلب</h4>${p.requirements.length?'<ul>'+p.requirements.map(r=>`<li><strong>${E(r.label)} <small>${r.required?'مطلوب':'اختياري'}</small></strong>${r.help_text?`<p>${E(r.help_text)}</p>`:''}${r.input_type==='select'?`<p>الخيارات: ${E((r.options_json||[]).join('، '))}</p>`:''}</li>`).join('')+'</ul>':'<p>لا توجد بيانات إضافية مطلوبة في هذه الباقة.</p>'}</section>${p.instructions.map(i=>`<section class="service-instruction"><h4>${E(stageNames[i.stage]||i.title)}</h4><p>${E(i.body)}</p></section>`).join('')}<div class="service-package-action"><p>الدفع والتفعيل يؤكدهما الأدمن يدويًا بعد مراجعة الطلب.</p><a class="button" href="/account?service=${encodeURIComponent(service.slug)}&package=${encodeURIComponent(p.id)}">${p.pricing_mode==='quote'?'متابعة لطلب عرض سعر':'متابعة للاشتراك'} ←</a></div></article>`).join('')+'</div>'}catch(error){$('#service-feedback').textContent=error.message;$('#service-overview').replaceChildren();$('#service-packages').replaceChildren()}})();
